public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int N = sc.nextInt();
    int Q = sc.nextInt();
    boolean[] hasTooth = new boolean[N];

    for (int i = 0; i < Q; i++) {
        int treatment = sc.nextInt();
        hasTooth[treatment - 1] = !hasTooth[treatment - 1];
    }

    int count = 0;
    for (boolean tooth : hasTooth) {
        if (tooth) {
            count++;
        }
    }

    System.out.println(count);
}
